import {businessPlan} from './fixtures/business-plan.mjs';
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import vm from 'node:vm';
import worker,{makeReport,makePdf,validate,chatPlan,intentOptions,parseEvents,generateGeminiReport,validateGeminiReport,businessQuestions,problemAreas,revenueBands,learningQuestions,learningUses} from '../worker/index.js';
const answers={business:'Bloom Studio',offer:'Brand design for cafés',audience:'Independent café owners',pain:'Standing out locally',channel:'Social media',goal:'Book five calls',stage:'Recently launched'};
const req=(path,data,headers={})=>new Request('https://example.com'+path,{method:'POST',headers:{origin:'https://example.com','content-type':'application/json',...headers},body:JSON.stringify(data)});
test('landing and client JavaScript parse, server secrets are absent',async()=>{const response=await worker.fetch(new Request('https://example.com/'));assert.equal(response.status,200);const html=await response.text();const script=html.match(/<script>([\s\S]*?)<\/script>/)[1];new vm.Script(script);assert.ok(!html.includes('Less busywork.<br><em>More possibility.</em>'));assert.ok(html.includes('data-landing="true"'));assert.ok(!html.includes('Bearer '));assert.ok(!html.includes('id="download"'));assert.ok(!html.includes('function makePdf'));assert.ok(!html.includes('reportDialog'));assert.ok(html.includes("fetch('/api/plan'"));});
test('report depends on supplied business and acquisition channel',async()=>{const r=await worker.fetch(req('/api/report',{answers}));assert.equal(r.status,200);const {report}=await r.json();assert.ok(report.title.includes('Bloom Studio'));assert.ok(report.sections[4][1].includes('three short posts'));const other=makeReport({...answers,channel:'Referrals'});assert.ok(other.sections[4][1].includes('specific introduction'));});
test('rejects incomplete answers, oversized bodies, cross-origin requests and missing consent',async()=>{assert.throws(()=>validate({business:'x'}));assert.throws(()=>validate({...answers,business:'x'.repeat(81)}));assert.equal((await worker.fetch(req('/api/report',{answers},{origin:'https://attacker.com'}))).status,403);assert.equal((await worker.fetch(req('/api/report',{answers,website:'x'.repeat(10001)}))).status,413);assert.equal((await worker.fetch(req('/api/email',{answers,email:'person@example.com'}))).status,400);});
test('unconfigured email is honest and reports remain available',async()=>{const r=await worker.fetch(req('/api/email',{answers,email:'person@example.com',consent:true}));assert.equal(r.status,503);assert.match((await r.json()).error,/not configured/);const status=await worker.fetch(new Request('https://example.com/api/status'));assert.deepEqual(await status.json(),{emailEnabled:false,reportEnabled:false,telegramEnabled:false});});
test('PDFs parse and stay one page even at maximum valid field sizes',()=>{for(const [name,a]of [['sample',answers],['max',Object.fromEntries(Object.entries({business:80,offer:240,audience:240,pain:240,channel:120,goal:200,stage:100}).map(([k,n])=>[k,'W'.repeat(n)]))]]){const file='/tmp/customer-insider-'+name+'.pdf';const bytes=makePdf(makeReport(validate(a)));writeFileSync(file,bytes);const text=new TextDecoder().decode(bytes);assert.match(text,/\/Count 1/);assert.match(text,/CUSTOMER INSIDER/);assert.match(text,/MEASURE WHAT MATTERS/);}});
test('email sends actual PDF attachment, idempotency key and handles provider errors',async()=>{const original=globalThis.fetch;let payload,idem;try{globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});assert.equal(url,'https://api.brevo.com/v3/smtp/email');payload=JSON.parse(options.body);idem=JSON.parse(options.body).headers.idempotencyKey;return new Response(JSON.stringify({messageId:'test-id'}),{status:200});};const data={answers,email:'person@example.com',consent:true};const env={BREVO_API_KEY:'test-only',BREVO_FROM_EMAIL:'reports@example.com'};let r=await worker.fetch(req('/api/email',data),env);assert.equal(r.status,200);assert.equal((await r.json()).accepted,true);assert.equal(payload.to[0].email,data.email);assert.ok(Buffer.from(payload.attachment[0].content,'base64').toString().startsWith('%PDF-1.4'));const first=idem;r=await worker.fetch(req('/api/email',data),env);assert.equal(idem,first);globalThis.fetch=async()=>new Response('provider failed',{status:500});r=await worker.fetch(req('/api/email',data),env);assert.equal(r.status,502);assert.ok(!(await r.text()).includes('accepted'));}finally{globalThis.fetch=original;}});
test('email endpoint rejects honeypots and malformed recipients before contacting provider',async()=>{const env={BREVO_API_KEY:'test-only',BREVO_FROM_EMAIL:'reports@example.com'};assert.equal((await worker.fetch(req('/api/email',{answers,email:'bad-address',consent:true}),env)).status,400);assert.equal((await worker.fetch(req('/api/email',{answers,email:'person@example.com',consent:true,website:'bot'}),env)).status,400);});
test('email requests are capped within the current Worker isolate',async()=>{const original=globalThis.fetch;try{globalThis.fetch=async()=>new Response(JSON.stringify({messageId:'mock-message'}),{status:200});const data={answers,email:'person@example.com',consent:true};const env={BREVO_API_KEY:'test-only',BREVO_FROM_EMAIL:'reports@example.com'};for(let i=0;i<5;i++){const r=await worker.fetch(req('/api/email',data,{'cf-connecting-ip':'192.0.2.99'}),env);assert.equal(r.status,200);}assert.equal((await worker.fetch(req('/api/email',data,{'cf-connecting-ip':'192.0.2.99'}),env)).status,429);}finally{globalThis.fetch=original;}});


const {openLocalDatabase}=await import('../db/local.mjs');
const {readFileSync,unlinkSync}=await import('node:fs');
const ownerEnv=DB=>({DB,ADMIN_EMAIL:'owner@example.com'});
const storageData=()=>({answers,save:true,storageConsent:true,submissionKey:crypto.randomUUID(),submissionToken:crypto.randomUUID()});
const ownerRequest=path=>new Request('https://example.com'+path,{headers:{'oai-authenticated-user-email':'owner@example.com'}});
test('completed interviews persist across database reopen, retries do not duplicate them, samples do not save',async()=>{const path='/tmp/customer-insider-storage-'+crypto.randomUUID()+'.sqlite';let DB=openLocalDatabase(path);try{const data=storageData();let r=await worker.fetch(req('/api/report',data),ownerEnv(DB));assert.equal(r.status,200);assert.equal((await r.json()).saved,true);r=await worker.fetch(req('/api/report',data),ownerEnv(DB));assert.equal(r.status,200);await worker.fetch(req('/api/report',{answers}),ownerEnv(DB));DB.close();DB=openLocalDatabase(path);const result=await DB.prepare('SELECT * FROM submissions').all();assert.equal(result.results.length,1);assert.deepEqual(JSON.parse(result.results[0].answers_json),answers);assert.ok(result.results[0].storage_consent_at);}finally{DB.close();unlinkSync(path);}});
test('saving requires storage consent and an available database',async()=>{const DB=openLocalDatabase(':memory:');try{const data=storageData();assert.equal((await worker.fetch(req('/api/report',{...data,storageConsent:false}),{DB})).status,400);assert.equal((await worker.fetch(req('/api/report',data),{})).status,503);assert.equal((await DB.prepare('SELECT * FROM submissions').all()).results.length,0);}finally{DB.close();}});
test('one visitor cannot overwrite another saved response or attach email to it',async()=>{const DB=openLocalDatabase(':memory:');try{const data=storageData();await worker.fetch(req('/api/report',data),{DB});assert.equal((await worker.fetch(req('/api/report',{...data,submissionToken:crypto.randomUUID()}),{DB})).status,409);assert.equal((await worker.fetch(req('/api/email',{answers,email:'visitor@example.com',consent:true,submissionId:data.submissionKey,submissionToken:crypto.randomUUID()}),{DB})).status,403);assert.equal((await DB.prepare('SELECT * FROM email_requests').all()).results.length,0);}finally{DB.close();}});
test('database links recipient, explicit consent and accepted status to the right interview',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;try{globalThis.fetch=async()=>new Response(JSON.stringify({messageId:'email-test-id'}),{status:200});const env={...ownerEnv(DB),BREVO_API_KEY:'test-only',BREVO_FROM_EMAIL:'reports@example.com'};const data=storageData();await worker.fetch(req('/api/report',data),env);const response=await worker.fetch(req('/api/email',{answers,email:'visitor@example.com',consent:true,submissionId:data.submissionKey,submissionToken:data.submissionToken}),env);assert.equal(response.status,200);const saved=await DB.prepare('SELECT * FROM email_requests').first();assert.equal(saved.submission_id,data.submissionKey);assert.equal(saved.recipient,'visitor@example.com');assert.equal(saved.status,'accepted');assert.equal(saved.provider_id,'email-test-id');assert.ok(saved.consent_at);}finally{globalThis.fetch=original;DB.close();}});
test('owner-only administration exports parsed responses without access tokens',async()=>{const DB=openLocalDatabase(':memory:');try{const env=ownerEnv(DB);const data=storageData();await worker.fetch(req('/api/report',data),env);for(const path of ['/admin','/api/admin/responses']){assert.equal((await worker.fetch(new Request('https://example.com'+path),env)).status,403);assert.equal((await worker.fetch(new Request('https://example.com'+path,{headers:{'oai-authenticated-user-email':'someone@example.com'}}),env)).status,403);}const response=await worker.fetch(ownerRequest('/api/admin/responses'),env);assert.equal(response.status,200);const text=await response.text();assert.ok(!text.includes(data.submissionToken));const exported=JSON.parse(text);assert.deepEqual(exported.records[0].answers,answers);assert.equal(exported.nextCursor,null);const html=await(await worker.fetch(ownerRequest('/admin'),env)).text();new vm.Script(html.match(/<script>([\s\S]*?)<\/script>/)[1]);assert.equal((await worker.fetch(ownerRequest('/api/admin/responses?cursor=broken'),env)).status,400);}finally{DB.close();}});
test('JSON export pagination includes all responses even with matching timestamps',async()=>{const DB=openLocalDatabase(':memory:');try{const env=ownerEnv(DB);for(let i=0;i<51;i++)await worker.fetch(req('/api/report',storageData()),env);let cursor=null;const ids=[];do{const response=await worker.fetch(ownerRequest('/api/admin/responses'+(cursor?'?cursor='+encodeURIComponent(cursor):'')),env);assert.equal(response.status,200);const data=await response.json();ids.push(...data.records.map(r=>r.id));cursor=data.nextCursor;}while(cursor);assert.equal(ids.length,51);assert.equal(new Set(ids).size,51);}finally{DB.close();}});

test('Seyi asks five business questions with department and revenue choices',()=>{
  assert.equal(chatPlan([]).text,'Hi, I’m Seyi 👋 What’s your name?');
  assert.deepEqual(chatPlan(['Ada']).choices,intentOptions);
  for(const path of [intentOptions[1],'I want to build automation for businesses']){
    const turns=['Ada',path];let plan=chatPlan(turns);assert.equal(plan.questionNumber,1);assert.ok(plan.text.endsWith(businessQuestions[0]));assert.match(plan.text,/five questions/);
    turns.push('Acme Foods');plan=chatPlan(turns);assert.equal(plan.field,'role');assert.ok(plan.text.endsWith(businessQuestions[1]));
    turns.push('Founder');plan=chatPlan(turns);assert.equal(plan.questionNumber,3);assert.ok(plan.text.endsWith(businessQuestions[2]));assert.deepEqual(plan.choices,['Marketing','Sales','Operations','Finance']);
    turns.push('Operations');plan=chatPlan(turns);assert.equal(plan.questionNumber,4);assert.ok(plan.text.endsWith(businessQuestions[3]));assert.deepEqual(plan.choices,['Under $10k','$10k-$100k','$100k-$500k','Above $500k']);turns.push('$10k-$100k');plan=chatPlan(turns);assert.equal(plan.questionNumber,5);assert.ok(plan.text.endsWith(businessQuestions[4]));assert.equal(plan.maxLength,1200);
    turns.push('We have a small team and need to reduce manual order entry.');assert.equal(chatPlan(turns).stage,'complete');
  }
  assert.throws(()=>chatPlan(['Ada','other']));assert.throws(()=>chatPlan(['a'.repeat(81)]));assert.throws(()=>chatPlan(new Array(8).fill('x')));
  assert.throws(()=>chatPlan(['Ada',intentOptions[0],'Acme','Founder','Other']));
});
const collect=async r=>{const result=[];for await(const e of parseEvents(r.body))result.push(e);return result;};
test('guided replies use SSE metadata and incremental text events without an AI key',async()=>{const response=await worker.fetch(req('/api/chat',{turns:[]}));assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/text\/event-stream/);const events=await collect(response);assert.equal(events[0].stage,'name');assert.equal(events[0].mode,'guided');assert.ok(events.filter(e=>e.type==='delta').length>1);assert.equal(events.filter(e=>e.type==='delta').map(e=>e.text).join(''),'Hi, I’m Seyi 👋 What’s your name?');assert.equal(events.at(-1).type,'done');});
function providerStream(events){const text=events.map(e=>'data: '+JSON.stringify(e)+'\r\n\r\n').join('');const bytes=new TextEncoder().encode(text);return new ReadableStream({start(c){for(let i=0;i<bytes.length;i+=3)c.enqueue(bytes.slice(i,i+3));c.close();}});}
test('AI deltas stream through the server and parser handles split UTF-8 and CRLF frames',async()=>{const original=globalThis.fetch;try{let posted;globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});assert.equal(url,'https://api.openai.com/v1/responses');posted=JSON.parse(options.body);return new Response(providerStream([{type:'response.output_text.delta',delta:'Thanks, Adé. '},{type:'response.output_text.delta',delta:'I have your business name.'},{type:'response.completed'}]));};const response=await worker.fetch(req('/api/chat',{turns:['Adé',intentOptions[1],'A café selling lunches']}),{OPENAI_API_KEY:'test-key',OPENAI_MODEL:'test-model'});const events=await collect(response);assert.equal(events[0].mode,'ai');assert.equal(events.filter(e=>e.type==='delta').map(e=>e.text).join(''),'Thanks, Adé. I have your business name.\n\n'+chatPlan(['Adé',intentOptions[1],'A café selling lunches']).text);assert.equal(events.at(-1).type,'done');assert.equal(posted.stream,true);assert.equal(posted.store,false);assert.ok(posted.input.includes('café'));}finally{globalThis.fetch=original;}});
test('interrupted AI replaces the partial reply with a complete guided question',async()=>{const original=globalThis.fetch;try{globalThis.fetch=async()=>new Response(providerStream([{type:'response.output_text.delta',delta:'partial'},{type:'response.failed'}]));const turns=['Ada',intentOptions[0],'Local cafés'];const events=await collect(await worker.fetch(req('/api/chat',{turns}),{OPENAI_API_KEY:'test-key',OPENAI_MODEL:'test-model'}));const reset=events.findIndex(e=>e.type==='reset');assert.ok(reset>0);assert.equal(events[reset].mode,'guided');assert.equal(events.slice(reset+1).filter(e=>e.type==='delta').map(e=>e.text).join(''),chatPlan(turns).text);assert.equal(events.at(-1).type,'done');}finally{globalThis.fetch=original;}});

test('AI text is available before provider completion, rather than buffered as a whole response',async()=>{const original=globalThis.fetch;let upstream;try{globalThis.fetch=async()=>new Response(new ReadableStream({start(c){upstream=c;c.enqueue(new TextEncoder().encode('data: '+JSON.stringify({type:'response.output_text.delta',delta:'First words'})+'\n\n'));}}));const response=await worker.fetch(req('/api/chat',{turns:['Ada',intentOptions[1],'A café']}),{OPENAI_API_KEY:'test-key',OPENAI_MODEL:'test-model'});const reader=response.body.getReader();const decoder=new TextDecoder();let text='';while(!text.includes('First words')){const result=await reader.read();assert.equal(result.done,false);text+=decoder.decode(result.value);}assert.ok(!text.includes('"type":"done"'));upstream.enqueue(new TextEncoder().encode('data: '+JSON.stringify({type:'response.completed'})+'\n\n'));upstream.close();while(true){const result=await reader.read();if(result.done)break;text+=decoder.decode(result.value);}assert.ok(text.includes('"type":"done"'));}finally{globalThis.fetch=original;}});

const automationAnswers={flowVersion:2,visitorName:'Ada',intent:'sales',context:'A café selling lunches',currentProcess:'WhatsApp messages and spreadsheets',challenge:'Late follow-up',outcome:'Reply within an hour'};
const geminiValue={title:'Ada’s café automation plan',businessSnapshot:'A café serving lunches, based on the supplied answers.',priorityCustomer:'Current lunch customers; confirm which segment contacts the café most often.',opportunity:'Reduce the delay between a WhatsApp enquiry and a staff follow-up.',workflow:'New enquiry → lead tracker → acknowledgement → staff review. Confirm tool access first.',sevenDayPlan:'Map ten recent enquiries, build a small reminder workflow and trial it with staff for seven days.',successMetric:'Record time to first reply and completed follow-ups before and during the trial.'};
const geminiResponse=value=>new Response(JSON.stringify({candidates:[{finishReason:'STOP',content:{parts:[{text:JSON.stringify(value)}]}}]}),{status:200});
const geminiData=()=>({...storageData(),answers:automationAnswers,email:'Ada@Example.com',aiConsent:true});
const geminiEnv=DB=>({...ownerEnv(DB),GEMINI_API_KEY:'gemini-test-key',GEMINI_MODEL:'gemini-test-model'});
const reportRequest=(data,ip)=>req('/api/report',data,{'cf-connecting-ip':ip});
test('Gemini personalizes the saved report while contact email stays out of the model request',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;try{let payload;globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});assert.equal(url,'https://generativelanguage.googleapis.com/v1beta/models/gemini-test-model:generateContent');assert.equal(options.headers['x-goog-api-key'],'gemini-test-key');payload=JSON.parse(options.body);return geminiResponse(geminiValue);};const data=geminiData();const response=await worker.fetch(reportRequest(data,'192.0.2.41'),geminiEnv(DB));assert.equal(response.status,200);const r=await response.json();assert.equal(r.report.provider,'gemini');assert.equal(r.report.model,'gemini-test-model');assert.match(r.report.sections[3][1],/lead tracker/);const text=payload.contents[0].parts[0].text;assert.ok(text.includes('café'));assert.ok(!text.includes(data.email));assert.equal(payload.generationConfig.responseFormat.text.mimeType,'APPLICATION_JSON');const row=await DB.prepare('SELECT * FROM submissions').first();assert.equal(row.email,'ada@example.com');assert.equal(row.report_status,'ready');assert.equal(row.consent_version,'2026-10-29-v3');assert.deepEqual(JSON.parse(row.report_json),r.report);writeFileSync('/tmp/seyi-gemini-sample.pdf',makePdf(r.report));}finally{globalThis.fetch=original;DB.close();}});
test('contact email and answers survive when the Gemini key is not yet configured',async()=>{const DB=openLocalDatabase(':memory:');try{const response=await worker.fetch(reportRequest(geminiData(),'192.0.2.42'),ownerEnv(DB));assert.equal(response.status,503);const result=await response.json();assert.equal(result.contactSaved,true);assert.equal(result.code,'GEMINI_NOT_CONFIGURED');const row=await DB.prepare('SELECT * FROM submissions').first();assert.equal(row.email,'ada@example.com');assert.equal(row.report_status,'awaiting_configuration');assert.equal(JSON.parse(row.report_json),null);const exported=await(await worker.fetch(ownerRequest('/api/admin/responses'),ownerEnv(DB))).json();assert.equal(exported.records[0].email,'ada@example.com');assert.equal(exported.records[0].report,null);assert.equal(exported.records[0].reportStatus,'awaiting_configuration');}finally{DB.close();}});
test('invalid contact email or missing AI consent is rejected before persistence or model calls',async()=>{const DB=openLocalDatabase(':memory:');try{for(const change of [{email:'invalid'},{email:''},{aiConsent:false},{storageConsent:false},{save:false}])assert.equal((await worker.fetch(reportRequest({...geminiData(),...change},'192.0.2.43'),geminiEnv(DB))).status,400);assert.equal((await DB.prepare('SELECT * FROM submissions').all()).results.length,0);}finally{DB.close();}});
test('failed or malformed Gemini output retains the contact without falling back to a generic report',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;try{for(const response of [new Response('provider internal key data',{status:500}),geminiResponse({title:'Missing sections'}),new Response(JSON.stringify({candidates:[{finishReason:'SAFETY',content:{parts:[]}}]}))]){globalThis.fetch=async()=>response;const r=await worker.fetch(reportRequest(geminiData(),'192.0.2.44'),geminiEnv(DB));assert.equal(r.status,502);const body=await r.json();assert.equal(body.contactSaved,true);assert.ok(!body.report);assert.ok(!JSON.stringify(body).includes('provider internal'));}const rows=(await DB.prepare('SELECT * FROM submissions').all()).results;assert.equal(rows.length,3);assert.ok(rows.every(r=>r.email==='ada@example.com'&&r.report_status==='failed'&&JSON.parse(r.report_json)===null));}finally{globalThis.fetch=original;DB.close();}});
test('repeated generation returns the same saved Gemini report without charging another model call',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;try{let calls=0;globalThis.fetch=async()=>{calls++;return geminiResponse(geminiValue);};const data=geminiData();const env=geminiEnv(DB);const first=await(await worker.fetch(reportRequest(data,'192.0.2.45'),env)).json();const second=await(await worker.fetch(reportRequest(data,'192.0.2.45'),env)).json();assert.equal(calls,1);assert.deepEqual(first.report,second.report);assert.equal((await DB.prepare('SELECT * FROM submissions').all()).results.length,1);assert.equal((await worker.fetch(reportRequest({...data,submissionToken:crypto.randomUUID()},'192.0.2.45'),env)).status,409);}finally{globalThis.fetch=original;DB.close();}});
test('email attaches the exact saved Gemini PDF and never regenerates a generic report',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;try{let mail;globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});if(url.startsWith('https://generativelanguage.googleapis.com'))return geminiResponse(geminiValue);assert.equal(url,'https://api.brevo.com/v3/smtp/email');mail=JSON.parse(options.body);return new Response(JSON.stringify({messageId:'gemini-mail-test'}));};const data=geminiData();const env={...geminiEnv(DB),BREVO_API_KEY:'test-only',BREVO_FROM_EMAIL:'reports@example.com'};const generated=await(await worker.fetch(reportRequest(data,'192.0.2.46'),env)).json();const sent=await worker.fetch(req('/api/email',{answers:automationAnswers,email:'ada@example.com',consent:true,submissionId:data.submissionKey,submissionToken:data.submissionToken},{'cf-connecting-ip':'192.0.2.146'}),env);assert.equal(sent.status,200);assert.deepEqual(Buffer.from(mail.attachment[0].content,'base64'),Buffer.from(makePdf(generated.report)));assert.ok(Buffer.from(mail.attachment[0].content,'base64').toString().includes('lead tracker'));}finally{globalThis.fetch=original;DB.close();}});
test('local migration upgrades existing records without deleting them and is safe to reopen',async()=>{const {DatabaseSync}=await import('node:sqlite');const path='/tmp/seyi-upgrade-'+crypto.randomUUID()+'.sqlite';const old=new DatabaseSync(path);old.exec(readFileSync(new URL('../drizzle/0000_submissions.sql',import.meta.url),'utf8'));old.prepare('INSERT INTO submissions (id, access_token, created_at, answers_json, report_json, storage_consent_at) VALUES (?, ?, ?, ?, ?, ?)').run('legacy','token','2026-10-28',JSON.stringify(answers),JSON.stringify(makeReport(answers)),'2026-10-28');old.close();let DB=openLocalDatabase(path);try{let row=await DB.prepare('SELECT * FROM submissions WHERE id = ?').bind('legacy').first();assert.equal(row.report_status,'ready');assert.equal(row.email,null);assert.deepEqual(JSON.parse(row.answers_json),answers);DB.close();DB=openLocalDatabase(path);row=await DB.prepare('SELECT * FROM submissions WHERE id = ?').bind('legacy').first();assert.ok(row);}finally{DB.close();unlinkSync(path);}});
test('concurrent report requests share a database lock instead of generating twice',async()=>{const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;let release;let began;const started=new Promise(r=>began=r);try{let calls=0;globalThis.fetch=async()=>{calls++;began();await new Promise(r=>release=r);return geminiResponse(geminiValue);};const data=geminiData();const env=geminiEnv(DB);const first=worker.fetch(reportRequest(data,'192.0.2.47'),env);await started;const second=await worker.fetch(reportRequest(data,'192.0.2.47'),env);assert.equal(second.status,409);release();assert.equal((await first).status,200);assert.equal(calls,1);}finally{globalThis.fetch=original;DB.close();}});
test('local API settings are reloaded after edits without restarting and external environment keeps precedence',async()=>{const {localEnvironment}=await import('../config/local-env.mjs');const path='/tmp/seyi-env-test-'+crypto.randomUUID();try{assert.deepEqual(localEnvironment(path,{}),{});writeFileSync(path,'GEMINI_API_KEY=test-one\nGEMINI_MODEL=gemini-test-model\n');assert.equal(localEnvironment(path,{}).GEMINI_API_KEY,'test-one');writeFileSync(path,'GEMINI_API_KEY=test-two\n');assert.equal(localEnvironment(path,{}).GEMINI_API_KEY,'test-two');assert.equal(localEnvironment(path,{GEMINI_API_KEY:'external-test'}).GEMINI_API_KEY,'external-test');}finally{try{unlinkSync(path);}catch{}}});

const businessAnswers={flowVersion:3,visitorName:'Ada',intent:'sales',businessName:'Acme Foods',role:'Founder',problemArea:'Operations',criticalContext:'Our team is small and we need to reduce manual order entry before expanding.'};
test('new business schema stores explicit names, roles, problem areas and critical context',async()=>{
  assert.deepEqual(validate(businessAnswers),{flowVersion:3,visitorName:'Ada',intent:'sales',businessName:'Acme Foods',role:'Founder',criticalContext:businessAnswers.criticalContext,problemArea:'Operations'});
  for(const area of problemAreas)assert.equal(validate({...businessAnswers,problemArea:area}).problemArea,area);
  assert.throws(()=>validate({...businessAnswers,problemArea:'Other'}));assert.throws(()=>validate({...businessAnswers,criticalContext:'x'.repeat(1201)}));
  assert.equal(validate({...businessAnswers,criticalContext:'x'.repeat(1200)}).criticalContext.length,1200);
  const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;
  try{let input;globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});input=JSON.parse(JSON.parse(options.body).contents[0].parts[0].text);return geminiResponse(businessPlan);};
    const data={...geminiData(),answers:businessAnswers};const response=await worker.fetch(reportRequest(data,'192.0.2.61'),geminiEnv(DB));assert.equal(response.status,200);assert.deepEqual(input,validate(businessAnswers));assert.ok(!('currentProcess' in input));
    const saved=await DB.prepare('SELECT answers_json FROM submissions').first();assert.equal(JSON.parse(saved.answers_json).businessName,'Acme Foods');const exported=await(await worker.fetch(ownerRequest('/api/admin/responses'),ownerEnv(DB))).json();assert.equal(exported.records[0].answers.problemArea,'Operations');
  }finally{globalThis.fetch=original;DB.close();}
});
