test('learning path asks only its four questions and offers the two application goals',()=>{
  assert.equal(intentOptions[0],'I want to learn automation');
  for(const useCase of learningUses){
    const turns=['Ada',intentOptions[0]];let plan=chatPlan(turns);assert.equal(plan.questionCount,4);assert.equal(plan.field,'location');assert.ok(plan.text.endsWith(learningQuestions[0]));
    turns.push('Lagos, Nigeria');plan=chatPlan(turns);assert.equal(plan.questionNumber,2);assert.equal(plan.field,'useCase');assert.deepEqual(plan.choices,learningUses);
    turns.push(useCase);plan=chatPlan(turns);assert.equal(plan.field,'currentTools');assert.ok(plan.text.endsWith(learningQuestions[2]));assert.equal(plan.maxLength,600);
    turns.push('WhatsApp, Gmail and Excel');plan=chatPlan(turns);assert.equal(plan.questionNumber,4);assert.equal(plan.field,'experience');assert.ok(plan.text.endsWith(learningQuestions[3]));
    turns.push('Starting completely from scratch');plan=chatPlan(turns);assert.equal(plan.stage,'complete');assert.equal(plan.questionCount,4);assert.equal(plan.intent,'learn');
  }
  assert.throws(()=>chatPlan(['Ada',intentOptions[0],'Lagos','Other']));
});
