test('business HTML and PDF preserve the template, fit A4, and keep every body line at 11pt',()=>{
  const r=createBusinessReport(businessPlan,currentBusiness,'test-model');
  assert.equal(r.title,'Acme Foods Business Growth Plan');assert.equal(r.sections.length,7);
  for(const heading of ['Your Business Today','Your Biggest Opportunity','How to Reach More Buyers','What May Be Holding You Back','Your Next 3 Actions','What to Automate First','Your First Step'])assert.ok(r.html.includes(heading));
  for(const placeholder of ['Nadine Philips','APPROVED','KEY INFORMATION','contenteditable','<script','https://'])assert.ok(!r.html.includes(placeholder));
  assert.match(r.html,/<table/);assert.match(r.html,/#c0d36c/);assert.match(r.html,/Arial,Helvetica/);
  assert.ok(businessRenderer.layout(r).text.every(t=>t.size>=11));
  const path='/tmp/seyi-business-layout-'+crypto.randomUUID()+'.pdf';writeFileSync(path,makePdf(r));
  try{const text=Buffer.from(makePdf(r)).toString();assert.match(text,/\/Count 1/);assert.match(text,/\/MediaBox \[0 0 595 842\]/);for(const [,body]of r.sections)assert.ok(text.includes(body.split(' ')[0]));}finally{unlinkSync(path);}
  const malicious=createBusinessReport({...businessPlan,firstStep:'<script>alert("test")</script>'},{businessName:'<img src=x onerror=alert(1)>'},'test');assert.ok(!malicious.html.includes('<script>'));assert.ok(!malicious.html.includes('<img src=x'));assert.ok(malicious.html.includes('&lt;script&gt;'));
  assert.throws(()=>createBusinessReport({...businessPlan,buyers:'See https://unverified.example'},currentBusiness,'test'));
  const oversized={...businessPlan,actions:businessPlan.actions.map(a=>({...a,what:'W'.repeat(390)})),today:'W'.repeat(990),opportunity:'W'.repeat(990),buyers:'W'.repeat(990)};
  assert.throws(()=>createBusinessReport(oversized,currentBusiness,'test'),/A4/);
});
test('current business flow uses the supplied prompt, retries oversized content, and automatically emails only the matching PDF',async()=>{
  const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;
  try{let calls=0;let mail;const prompts=[];globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});
    const payload=JSON.parse(options.body);
    if(url.startsWith('https://generativelanguage.googleapis.com')){calls++;prompts.push(payload);return geminiResponse(calls===1?{...businessPlan,today:'W'.repeat(990),opportunity:'W'.repeat(990),buyers:'W'.repeat(990)}:businessPlan);}
    assert.equal(url,'https://api.brevo.com/v3/smtp/email');mail=payload;return new Response(JSON.stringify({messageId:'business-mail'}));
  };
  const data={...storageData(),answers:currentBusiness,email:'ada@example.com',requestPlan:true};const env={...geminiEnv(DB),BREVO_API_KEY:'test',BREVO_FROM_EMAIL:'reports@example.com'};
  const response=await worker.fetch(reportRequest(data,'192.0.2.201'),env);assert.equal(response.status,200);const result=await response.json();assert.equal(calls,2);assert.equal(result.report.template,'business-v1');assert.match(prompts[0].systemInstruction.parts[0].text,/Grade 4/);assert.match(prompts[0].systemInstruction.parts[0].text,/350–450/);assert.equal(prompts[0].generationConfig.responseFormat.text.schema.properties.actions.minItems,3);assert.ok(!JSON.stringify(prompts).includes('ada@example.com'));
  const row=await DB.prepare('SELECT report_json FROM submissions WHERE id = ?').bind(data.submissionKey).first();assert.deepEqual(JSON.parse(row.report_json),result.report);
  const sent=await worker.fetch(req('/api/email',{answers:currentBusiness,email:data.email,consent:true,submissionId:data.submissionKey,submissionToken:data.submissionToken},{'cf-connecting-ip':'192.0.2.202'}),env);assert.equal(sent.status,200);assert.equal(mail.attachment.length,1);assert.equal(mail.attachment[0].name,'business-growth-plan.pdf');assert.deepEqual(Buffer.from(mail.attachment[0].content,'base64'),Buffer.from(makePdf(result.report)));assert.deepEqual(mail.to,[{email:data.email}]);assert.equal(result.emailDelivery.accepted,true);

  }finally{globalThis.fetch=original;DB.close();}
});
