test('Brevo authenticates server-side, uses its attachment schema and prevents concurrent duplicate sends',async()=>{
  const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;let release,started;
  const began=new Promise(r=>started=r);
  const learner={flowVersion:5,intent:'learn',visitorName:'Ada',location:'Lagos',useCase:learningUses[0],currentTools:'Gmail',experience:'Beginner'};
  const data={...storageData(),answers:learner,email:'ada@example.com',requestPlan:true};
  try{
    await worker.fetch(reportRequest(data,'192.0.2.210'),ownerEnv(DB));
    let calls=0;globalThis.fetch=async(url,options)=>{if(url==='https://api.brevo.com/v3/contacts')return new Response(null,{status:204});calls++;assert.equal(url,'https://api.brevo.com/v3/smtp/email');assert.equal(options.headers['api-key'],'brevo-test-key');assert.equal(options.headers.Authorization,undefined);const body=JSON.parse(options.body);assert.deepEqual(body.sender,{email:'reports@example.com',name:'Seyi Studio'});assert.deepEqual(body.replyTo,{email:'help@example.com'});assert.deepEqual(body.to,[{email:'ada@example.com'}]);assert.equal(body.attachment.length,1);assert.equal(body.attachment[0].name,'sales_automation_8_step_guide.pdf');assert.ok(!body.attachments);assert.match(body.headers.idempotencyKey,/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-a[0-9a-f]{3}-[0-9a-f]{12}$/);started();await new Promise(r=>release=r);return new Response(JSON.stringify({messageId:'brevo-confirmed'}),{status:201});};
    const env={...ownerEnv(DB),BREVO_API_KEY:'brevo-test-key',BREVO_FROM_EMAIL:'reports@example.com',BREVO_FROM_NAME:'Seyi Studio',BREVO_REPLY_TO_EMAIL:'help@example.com'};
    const email={answers:learner,email:data.email,consent:true,submissionId:data.submissionKey,submissionToken:data.submissionToken};
    const first=worker.fetch(req('/api/email',email,{'cf-connecting-ip':'192.0.2.211'}),env);await began;assert.equal((await worker.fetch(req('/api/email',email,{'cf-connecting-ip':'192.0.2.212'}),env)).status,409);release();assert.equal((await first).status,200);const cached=await worker.fetch(req('/api/email',email,{'cf-connecting-ip':'192.0.2.213'}),env);assert.equal((await cached.json()).accepted,true);assert.equal(calls,1);const delivery=await DB.prepare('SELECT status, provider_id FROM email_deliveries').first();assert.deepEqual({...delivery},{status:'accepted',provider_id:'brevo-confirmed'});
  }finally{release?.();globalThis.fetch=original;DB.close();}
});
