test('business plans append only relevant approved survey statistics with source and scope',async()=>{
  const {approvedSalesStatistics}=await import('../reports/business.js');
  for(const [id,context]of [['selling-time-2026','Our team wastes time on manual sales admin.'],['buyer-education-2026','Buyers need help understanding our offer.'],['buyer-decisions-2026','Our leads decide slowly and we miss follow-ups.']]){
    const report=createBusinessReport({...businessPlan,statisticId:id},{...currentBusiness,criticalContext:context},'test');assert.equal(report.statistic.id,id);assert.ok(report.content.blockers.includes(approvedSalesStatistics[id].text));assert.ok(report.content.blockers.includes('Salesforce, State of Sales, 7th edition (2026), pp. 3, 8'));assert.ok(report.content.blockers.includes('General context, not a result for your business.'));assert.equal(report.statistic.checkedAt,'2026-10-30');assert.equal(report.sections.length,7);assert.ok(businessRenderer.layout(report).bottom<=820);assert.ok(businessRenderer.layout(report).text.every(t=>t.size>=11));const pdf=Buffer.from(makePdf(report)).toString();assert.ok(pdf.includes('Survey context:'));assert.ok(pdf.includes('Salesforce'));
  }
  assert.throws(()=>createBusinessReport({...businessPlan,statisticId:'invented-99-percent'},currentBusiness,'test'),/Unknown statistic/);
  assert.throws(()=>createBusinessReport({...businessPlan,opportunity:'Automation guarantees 99% more sales.'},currentBusiness,'test'),/percentages must come/);
  const irrelevant=createBusinessReport({...businessPlan,statisticId:'selling-time-2026'},{...currentBusiness,criticalContext:'We need to reconcile supplier invoices.'},'test');assert.equal(irrelevant.statistic,null);
  const noStatistic=createBusinessReport({...businessPlan,statisticId:'none'},currentBusiness,'test');assert.equal(noStatistic.statistic,null);
  const supplied=createBusinessReport({...businessPlan,statisticId:'none',today:'You report a 10% reply rate. Check your records before setting a new target.'},{...currentBusiness,criticalContext:'We estimate a 10% reply rate.'},'test');assert.ok(supplied.content.today.includes('10%'));
});
