test('email-only submission acknowledges saved answers before Gemini finishes, survives disconnect, and prevents duplicate jobs',async()=>{
  const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;let release,started;const gate=new Promise(resolve=>{release=resolve;});const modelStarted=new Promise(resolve=>{started=resolve;});const jobs=[];let generations=0,mails=0;const lists=[];
  try{
    globalThis.fetch=async(url,options)=>{
      if(url.startsWith('https://generativelanguage.googleapis.com')){generations++;started();await gate;assert.equal(options.signal.aborted,false);return geminiResponse(businessPlan);}
      if(url==='https://api.brevo.com/v3/contacts'){lists.push(JSON.parse(options.body).listIds);return new Response(null,{status:204});}
      assert.equal(url,'https://api.brevo.com/v3/smtp/email');mails++;const payload=JSON.parse(options.body);assert.equal(payload.attachment[0].name,'business-growth-plan.pdf');assert.equal(payload.to[0].email,'ada@example.com');return new Response(JSON.stringify({messageId:'background-test'}));
    };
    const env={...geminiEnv(DB),BREVO_API_KEY:'test',BREVO_FROM_EMAIL:'reports@example.com'};const data={...storageData(),answers:currentBusiness,email:'Ada@Example.Com',requestPlan:true};const ctx={waitUntil(p){jobs.push(p);}};
    const abort=new AbortController();const request=new Request(req('/api/plan',data,{'cf-connecting-ip':'192.0.2.231'}),{signal:abort.signal});
    const response=await worker.fetch(request,env,ctx);assert.equal(response.status,202);const ack=await response.json();assert.equal(ack.status,'processing');assert.ok(!('report' in ack));assert.equal((await DB.prepare('SELECT email FROM submissions').first()).email,'ada@example.com');
    await modelStarted;abort.abort();assert.equal((await worker.fetch(req('/api/plan',data),env,ctx)).status,202);assert.equal(generations,1);
    const query={submissionKey:data.submissionKey,submissionToken:data.submissionToken};assert.equal((await worker.fetch(req('/api/plan/status',{...query,submissionToken:crypto.randomUUID()}),env)).status,404);
    assert.equal((await(await worker.fetch(req('/api/plan/status',query),env)).json()).status,'processing');
    release();await Promise.all(jobs);assert.equal(mails,1);assert.deepEqual(lists,[[9]]);assert.equal((await(await worker.fetch(req('/api/plan/status',query),env)).json()).status,'accepted');
    const repeated=await(await worker.fetch(req('/api/plan',data),env,ctx)).json();assert.equal(repeated.status,'accepted');assert.equal(mails,1);assert.equal(generations,1);
  }finally{release();await Promise.allSettled(jobs);globalThis.fetch=original;DB.close();}
});

test('background learner failure is retryable, uses the supplied PDF without Gemini, and adds list 10 after mail acceptance',async()=>{
  const DB=openLocalDatabase(':memory:');const original=globalThis.fetch;const jobs=[];let succeed=false,mails=0,contacts=0;
  try{
    globalThis.fetch=async(url,options)=>{
      if(url==='https://api.brevo.com/v3/contacts'){contacts++;assert.deepEqual(JSON.parse(options.body).listIds,[10]);return new Response(null,{status:204});}
      assert.equal(url,'https://api.brevo.com/v3/smtp/email');mails++;assert.equal(JSON.parse(options.body).attachment[0].name,'sales_automation_8_step_guide.pdf');return succeed?new Response(JSON.stringify({messageId:'background-learner'})):new Response('',{status:500});
    };
    const env={DB,BREVO_API_KEY:'test',BREVO_FROM_EMAIL:'reports@example.com'};const ctx={waitUntil(p){jobs.push(p);}};
    const data={...storageData(),answers:{flowVersion:5,intent:'learn',visitorName:'Ada',location:'Lagos',useCase:learningUses[0],currentTools:'Gmail',experience:'Beginner'},email:'ada@example.com',requestPlan:true};
    assert.equal((await worker.fetch(req('/api/plan',{...data,email:'bad'}),env,ctx)).status,400);assert.equal((await DB.prepare('SELECT * FROM submissions').all()).results.length,0);
    assert.equal((await worker.fetch(req('/api/plan',data,{'cf-connecting-ip':'192.0.2.232'}),env,ctx)).status,202);await Promise.all(jobs);assert.equal((await DB.prepare('SELECT status FROM plan_requests').first()).status,'failed');assert.equal(contacts,0);
    assert.equal((await worker.fetch(req('/api/plan',{...data,submissionToken:crypto.randomUUID()}),env,ctx)).status,409);
    succeed=true;assert.equal((await worker.fetch(req('/api/plan',data,{'cf-connecting-ip':'192.0.2.232'}),env,ctx)).status,202);await Promise.all(jobs);assert.equal((await DB.prepare('SELECT status FROM plan_requests').first()).status,'accepted');assert.equal(mails,2);assert.equal(contacts,1);
  }finally{await Promise.allSettled(jobs);globalThis.fetch=original;DB.close();}
});
